responses.text:
{
  "decision": "applies",
  "reasons": [
    "Applies because you sell to consumers in 10 EU countries — every online order from them is a distance contract covered by these rules.",
    "You are established in Germany, so the same rule reaches you as § 356a BGB, in force since 19 June 2026."
  ],
  "todos": [
    {
      "text": "Add a labelled, two-step withdrawal button to your storefront",
      "due": "2026-06-19",
      "quote": "the trader shall ensure that the consumer can also exercise the right of withdrawal by means of a withdrawal function"
    },
    {
      "text": "Label the button 'withdraw contract here' (or an equally clear wording)",
      "due": "2026-06-19",
      "quote": "The withdrawal function shall be labelled with the words 'withdraw contract here' or a corresponding unambiguous formulation in an easily legible manner"
    },
    {
      "text": "Send an automatic confirmation email whenever a customer uses it",
      "due": "2026-06-19",
      "quote": "the trader shall communicate to the consumer without undue delay an acknowledgement of receipt of the withdrawal on a durable medium"
    }
  ]
}
